CREATE    VIEW [FO].[vwProject]
AS 
SELECT 
	T7.DISPLAYVALUE AS [DIMENSIONDISPLAYVALUE],
	T1.PROJID AS [PROJECTID],
	T1.ALTERNATEBUDGETPROJECT AS [ALTERNATEPROJECT],
	T1.ASSETID AS [FIXEDASSETNUMBER],
	T1.BANKDOCUMENTTYPE AS [BANKDOCUMENTTYPE],
	T1.CERTIFIEDPAYROLL AS [CERTIFIEDPAYROLL],
	T1.CHECKBUDGET AS [CANVERIFYCOSTAGAINSTREMAININGFORECAST],
	T1.COMPLETESCHEDULED AS [TASKCOMPLETELYSCHEDULED],
	T1.CONTRACTAMENDMENT_SA AS [ZAKATCONTRACTAMENDMENT],
	T1.CONTRACTDATE_SA [ZAKATCONTRACTDATE],
	T1.CONTRACTPERIOD_SA AS [ZAKATCONTRACTPERIOD],
	T1.CONTRACTVALUE_SA AS [ZAKATPROJECTVALUE],
	T1.CREATED AS [DATEOFCREATION],
	T1.CUSTACCOUNT AS [CUSTOMERACCOUNT],
	T1.DLVNAME AS [DELIVERYNAME],
	T1.EMAIL AS [EMAIL],
	T1.ENDDATE AS [ACTUALENDDATE],
	T1.EXTENSIONDATE AS [EXTENSIONDATE],
	T1.FORMAT AS [SUBPROJECTIDFORMAT],
	T1.HEADER AS [HEADER],
	T1.JOBID AS [JOBIDENTIFICATION],
	T1.JOBPAYTYPE AS [JOBPAYTYPE],
	T1.MINTIMEINCREMENT AS [MINIMUMTIMEINCREMENT],
	T1.NAME AS [PROJECTNAME],
	T8.PROJID AS [PARENTPROJECT],
	T1.PROJBUDGETARYCONTROLON AS [TRANSACTIONTYPESCONTROLLED],
	T1.PROJBUDGETINTERVAL AS [BUDGETCONTROLINTERVAL],
	T1.PROJBUDGETMANAGEMENT AS [PROJECTBUDGETMANAGEMENT],
	T1.PROJBUDGETOVERRUNOPTION AS [BUDGETOVERRUNDEFAULT],
	T1.PROJCARRYFORWARDNEGATIVEBUDGET AS [ALLOWNEGATIVEBUDGETSTOBECARRIEDFORWARD],
	T1.PROJCARRYFORWARDREMAININGBUDGET AS [CANCARRYFORWARDREMAININGBUDGETS],
	T1.PROJECTEDENDDATE AS [PROJECTEDENDDATE],
	T1.PROJECTEDSTARTDATE AS [PROJECTEDSTARTDATE],
	T1.PROJGROUPID AS [PROJECTGROUP],
	T1.PROJINVOICEPROJID AS [PROJECTCONTRACTID],
	T1.PROJLEDGERPOSTING AS [LEDGERPOSTINGSORTPRIORITY],
	T1.PROJLINEPROPERTYSEARCH AS [SEARCHPRIORITY],
	T1.PROJPRICEGROUP AS [SALESPRICEGROUP],
	T1.PSADOINVOICECOST AS [INVOICECOST],
	T1.PSAFORECASTMODELID AS [ACTIVEREVISION],
	T1.PSAFORECASTMODELIDEXTERNAL AS [EXTERNALREVISION],
	T1.PSAINVOICEMETHOD AS [INVOICINGMETHOD],
	T1.PSAPROJSTATUS AS [STATUS],
	T1.PSARESSCHEDSTATUS AS [SCHEDULESTATUS],
	T1.PSASCHEDCALENDARID AS [CALENDAR],
	T1.PSASCHEDDURATION AS [DURATIONINDAYS],
	T1.PSASCHEDEFFORT AS [TOTALEFFORTINHOURS],
	T1.PSASCHEDENDDATE AS [ENDDATE1],
	T1.PSASCHEDFROMTIME AS [STARTTIME],
	T1.PSASCHEDIGNORECALENDAR AS [PSASCHEDIGNORECALENDAR],
	T1.PSASCHEDSTARTDATE AS [STARTDATE1],
	T1.PSASCHEDTOTIME AS [ENDTIME],
	T1.PSASCHEDUSEDURATION AS [DURATIONDETERMINESENDDATE],
	T1.REQUIREACTIVITYEXPENSEFORECAST AS [ISACTIVITYREQUIREDFOREXPENSEFORECAST],
	T1.REQUIREACTIVITYEXPENSETRX AS [ISACTIVITYREQUIREDFOREXPENSETRANSACTION],
	T1.REQUIREACTIVITYHOURFORECAST AS [ISACTIVITYREQUIREDFORHOURFORECAST],
	T1.REQUIREACTIVITYHOURTRX AS [ISACTIVITYREQUIREDFORHOURTRANSACTION],
	T1.REQUIREACTIVITYITEMFORECAST AS [ISACTIVITYREQUIREDFORITEMFORECAST],
	T1.REQUIREACTIVITYITEMTRX AS [ISACTIVITYREQUIREDFORITEMTRANSACTION],
	T1.STARTDATE AS [ACTUALSTARTDATE],
	T1.STATUS AS [PROJECTSTAGE],
	T1.SUBJECT_SA AS [ZAKATSUBJECT],
	T1.TAXGROUPID AS [SALESTAXGROUP],
	T1.TEMPLATE AS [PROJECTTEMPLATE],
	T1.TIMEPOSTDETAILSUMMARY AS [POSTINGLEVEL],
	T1.TYPE AS [PROJECTTYPE],
	T1.USEALTERNATEPROJECT AS [CANUSEALTERNATEPROJECTBUDGET],
	T1.USEBUDGETING AS [CANUSEBUDGETCONTROL],
	T1.VALIDATEPROJCATEGORY AS [CATEGORY],
	T1.WIPPROJECT AS [ESTIMATEPROJECTID],
	T1.DESCRIPTION AS [DESCRIPTION],
	T1.TEMPLATEAPPLIED AS [TEMPLATEAPPLIED],
	T1.ALERTTIMEFRAMEWEEKS AS [ALERTTIMEFRAMEWEEKS],
	T2.LOCATIONID AS [LOCATIONID],
	T3.PERSONNELNUMBER AS [WORKERARCHITECTPERSONNELNUMBER],
	T4.PERSONNELNUMBER AS [WORKERRESPFINANCIALPERSONNELNUMBER],
	T5.PERSONNELNUMBER AS [WORKERRESPONSIBLEPERSONNELNUMBER],
	T6.PERSONNELNUMBER AS [WORKERRESPSALESPERSONNELNUMBER],
	T1.[PARTITION],
	T1.[DATAAREAID],
	t1.[DataLakeModified_DateTime]
FROM [synapse_fo].[PROJTABLE] T1
LEFT OUTER JOIN [synapse_fo].[LOGISTICSLOCATION] T2 ON (
		(T1.DELIVERYLOCATION = T2.RECID)
		AND (T1.PARTITION = T2.PARTITION)
		)
LEFT OUTER JOIN [synapse_fo].[HCMWORKER] T3 ON (
		(T1.WORKERPSAARCHITECT = T3.RECID)
		AND (T1.PARTITION = T3.PARTITION)
		)
LEFT OUTER JOIN [synapse_fo].[HCMWORKER] T4 ON (
		(T1.WORKERRESPONSIBLEFINANCIAL = T4.RECID)
		AND (T1.PARTITION = T4.PARTITION)
		)
LEFT OUTER JOIN [synapse_fo].[HCMWORKER] T5 ON (
		(T1.WORKERRESPONSIBLE = T5.RECID)
		AND (T1.PARTITION = T5.PARTITION)
		)
LEFT OUTER JOIN [synapse_fo].[HCMWORKER] T6 ON (
		(T1.WORKERRESPONSIBLESALES = T6.RECID)
		AND (T1.PARTITION = T6.PARTITION)
		)
LEFT OUTER JOIN [synapse_fo].[DIMENSIONSETENTITY_RICS] T7 ON (
		(T1.DEFAULTDIMENSION = T7.RECID)
		AND (T1.PARTITION = T7.PARTITION)
		)
LEFT OUTER JOIN [synapse_fo].[PROJTABLE] T8 ON (
		(
			(T1.PARENTID = T8.PROJID)
			AND (T1.DATAAREAID = T8.DATAAREAID)
			)
		AND (T1.PARTITION = T8.PARTITION)
		)
LEFT OUTER JOIN [synapse_fo].[PROJFUNDINGSOURCE] T9 ON (
		(
			(T1.DEFAULTFUNDINGSOURCE = T9.RECID)
			AND (T1.DATAAREAID = T9.DATAAREAID)
			)
		AND (T1.PARTITION = T9.PARTITION)
		)
